mapper.select:
SELECT  FROM provider_connection
WHERE user_id = #{userId}
ORDER BY provider

mapper.insert:
INSERT INTO provider_connection (
  user_id, provider, status, provider_account_email, granted_scopes, credential_ref, error_code
) VALUES (
  #{userId}, #{provider}, #{status}, #{providerAccountEmail}, #{grantedScopes}, #{credentialRef}, #{errorCode}
)
